class Directory:
    def __init__(self):
        self.entries = {}
        self.cached = None
    def put(self, name, value):
        self.entries[name] = value
        self.cached = None
    def delete(self, name):
        self.entries.pop(name, None)
        self.cached = None
    def listing(self):
        if self.cached is None: self.cached = sorted(self.entries)
        return list(self.cached)
